1	package pipeline
2	
3	import (
4		"fmt"
5		"image"
6		"math"
7		"math/rand"
8		"time"
9	
10		"strix-halo-vulkan/qimage/dit"
11		"strix-halo-vulkan/qimage/textenc"
12		qvae "strix-halo-vulkan/qimage/vae"
13		"strix-halo-vulkan/safetensors"
14		"strix-halo-vulkan/vk"
15		"strix-halo-vulkan/zimage/qwen"
16		"strix-halo-vulkan/zimage/tokenizer"
17		zvae "strix-halo-vulkan/zimage/vae"
18	)
19	
20	// The resident text-to-image pipeline — IMAGE.md Q6.
21	//
22	// Three staged models and nothing else: Q1's text encoder (zimage/qwen's
23	// GPUEncoder over the Qwen3-VL config), Q4's DiT, and Q5g's VAE decoder.
24	// Everything between them is arithmetic the host does per request — the
25	// template, the token drop, the layout, the schedule, the packing — so a
26	// request names a size and a step count rather than choosing a process.
27	//
28	// **The resolution is not part of what is resident.** The three arenas are
29	// sized once for the ceiling the flags asked for; a smaller image is the
30	// same three graphs with smaller numbers in them. That is the same split
31	// z-image's pipeline made and the same one api.ImageBackend's Geometry()
32	// expects: a size is a request parameter, a ceiling is residency.
33	//
34	// **The ceiling is the VAE's, and it is 1184², not 2048².** The decoder's
35	// activation arena is one storage buffer and this device caps one at 4 GiB
36	// − 4 (qimage/vae's TestArenaCeiling). New refuses a larger ceiling here,
37	// naming the number, rather than letting a buffer allocation fail three
38	// models into staging.
39	
40	const (
41		// SizeMultiple is what both sides of an image must be a multiple of: the
42		// VAE is 16x spatial and the VLM groups latent tokens 2x2, so a latent
43		// grid has to be even on both axes.
44		SizeMultiple = 32
45		// VAEScale is how much larger the image is than the latent grid.
46		VAEScale = 16
47	
48		// DefaultSteps is the checkpoint's own default schedule. Unlike
49		// Z-Image-Turbo's 8, this is not a distillation — 2.1 is a full model and
50		// 40 is what diffusers runs.
51		DefaultSteps = 40
52		// DefaultSize is the pipeline's default resolution, which is also
53		// diffusers' (the README's examples use 2048² explicitly instead).
54		DefaultSize = 1024
55		// DefaultMaxPrompt is the text encoder's token ceiling. A t2i prompt is
56		// the template plus the user's text, tens of tokens in practice.
57		DefaultMaxPrompt = 512
58	)
59	
60	// Options is what cmd/serve's flags come to.
61	type Options struct {
62		// Model is the Qwen-Image-2.1 checkpoint root, holding transformer/,
63		// text_encoder/, vae/, processor/ and scheduler/.
64		Model string
65		// Width and Height are the largest image the arenas are built for, and
66		// the size a request that names none gets.
67		Width, Height int
68		// Steps is the schedule a request that names none gets.
69		Steps int
70		// MaxPrompt is the longest prompt the text encoder is built for.
71		MaxPrompt int
72	}
73	
74	// geom is a resolved size, all the way down to the transformer's row count.
75	type geom struct {
76		width, height    int
77		latentH, latentW int
78		imgTokens        int
79	}
80	
81	func newGeom(width, height int) (geom, error) {
82		if width <= 0 || height <= 0 {
83			return geom{}, fmt.Errorf("pipeline: %dx%d is not an image", width, height)
84		}
85		if width%SizeMultiple != 0 || height%SizeMultiple != 0 {
86			return geom{}, fmt.Errorf("pipeline: %dx%d; both sides must be a multiple of %d",
87				width, height, SizeMultiple)
88		}
89		g := geom{width: width, height: height, latentH: height / VAEScale, latentW: width / VAEScale}
90		g.imgTokens = g.latentH * g.latentW
91		return g, nil
92	}
93	
94	// Pipeline is the three staged models plus what a request needs to drive
95	// them. One image at a time: the arenas are one image's.
96	type Pipeline struct {
97		opt Options
98	
99		tok  *tokenizer.Tokenizer
100		drop int
101		enc  *qwen.GPUEncoder
102		dt   *dit.GPU
103		dec  *qvae.GPUDecoder
104		vcfg *qvae.Config
105		scfg *SchedConfig
106	
107		def, max geom
108		steps    int
109	
110		// residency, for the startup banner.
111		encBytes, ditBytes, vaeBytes, actBytes int
112	}
113	
114	// New stages the whole pipeline on the device.
115	func New(dev *vk.Device, opt Options) (*Pipeline, error) {
116		if opt.Width == 0 && opt.Height == 0 {
117			opt.Width, opt.Height = DefaultSize, DefaultSize
118		}
119		if opt.Width == 0 {
120			opt.Width = opt.Height
121		}
122		if opt.Height == 0 {
123			opt.Height = opt.Width
124		}
125		if opt.Steps == 0 {
126			opt.Steps = DefaultSteps
127		}
128		if opt.MaxPrompt == 0 {
129			opt.MaxPrompt = DefaultMaxPrompt
130		}
131		max, err := newGeom(opt.Width, opt.Height)
132		if err != nil {
133			return nil, err
134		}
135	
136		p := &Pipeline{opt: opt, def: max, max: max, steps: opt.Steps}
137	
138		// The tokenizer and the two configs first: they are cheap, and a
139		// checkpoint that is missing a piece should say so before 30 GB of
140		// staging rather than after.
141		if p.tok, err = tokenizer.Load(opt.Model + "/processor"); err != nil {
142			return nil, fmt.Errorf("pipeline: tokenizer: %w", err)
143		}
144		if p.drop, err = textenc.DropTokens(p.tok); err != nil {
145			return nil, fmt.Errorf("pipeline: system-message length: %w", err)
146		}
147		tcfg, err := textenc.LoadConfig(opt.Model + "/text_encoder")
148		if err != nil {
149			return nil, fmt.Errorf("pipeline: text encoder config: %w", err)
150		}
151		if p.vcfg, err = qvae.LoadConfig(opt.Model + "/vae"); err != nil {
152			return nil, fmt.Errorf("pipeline: VAE config: %w", err)
153		}
154		if p.scfg, err = LoadSchedConfig(opt.Model + "/scheduler"); err != nil {
155			return nil, fmt.Errorf("pipeline: scheduler config: %w", err)
156		}
157	
158		// The VAE's ceiling, checked before anything is staged. It is a property
159		// of the graph and the device, so it costs a plan rather than an
160		// allocation — and the alternative is a caller discovering it from a
161		// failed 12 GB buffer after the other two models are already resident.
162		cpuDec, err := qvae.LoadDecoder(opt.Model+"/vae", p.vcfg)
163		if err != nil {
164			return nil, fmt.Errorf("pipeline: VAE decoder: %w", err)
165		}
166		need, err := qvae.ArenaBytes(cpuDec, max.latentH, max.latentW)
167		if err != nil {
168			return nil, err
169		}
170		if need > qvae.MaxStorageBufferBytes {
171			return nil, fmt.Errorf("pipeline: a %dx%d ceiling needs %d MB of VAE activations, "+
172				"past this device's %d MB single-buffer limit; the largest square is 1184x1184",
173				max.width, max.height, need>>20, qvae.MaxStorageBufferBytes>>20)
174		}
175	
176		set, err := safetensors.OpenSet(opt.Model + "/text_encoder")
177		if err != nil {
178			return nil, fmt.Errorf("pipeline: text encoder weights: %w", err)
179		}
180		if p.enc, err = qwen.NewGPUEncoder(dev, set, tcfg, tcfg.NumLayers, opt.MaxPrompt, nil); err != nil {
181			set.Close()
182			return nil, fmt.Errorf("pipeline: staging the text encoder: %w", err)
183		}
184		set.Close()
185	
186		// The DiT's row ceiling is the target's tokens plus the longest prompt:
187		// for t2i the prefix is the prompt and nothing else.
188		if p.dt, err = dit.NewGPU(dev, opt.Model+"/transformer", max.imgTokens+opt.MaxPrompt, opt.MaxPrompt); err != nil {
189			p.Destroy()
190			return nil, fmt.Errorf("pipeline: staging the transformer: %w", err)
191		}
192		if p.dec, err = qvae.NewGPUDecoder(dev, cpuDec, max.latentH, max.latentW); err != nil {
193			p.Destroy()
194			return nil, fmt.Errorf("pipeline: staging the VAE decoder: %w", err)
195		}
196	
197		p.encBytes = p.enc.WeightBytes()
198		p.vaeBytes = p.dec.WeightBytes()
199		p.ditBytes = p.dt.WeightBytes()
200		p.actBytes = p.enc.ActivationBytes() + p.dt.ActivationBytes() + p.dec.ActivationBytes()
201		return p, nil
202	}
203	
204	// Destroy releases the device residency.
205	func (p *Pipeline) Destroy() {
206		if p.dec != nil {
207			p.dec.Destroy()
208			p.dec = nil
209		}
210		if p.dt != nil {
211			p.dt.Destroy()
212			p.dt = nil
213		}
214		if p.enc != nil {
215			p.enc.Destroy()
216			p.enc = nil
217		}
218	}
219	
220	// Size is the image a request that names none gets; MaxSize is the ceiling.
221	func (p *Pipeline) Size() (width, height int)    { return p.def.width, p.def.height }
222	func (p *Pipeline) MaxSize() (width, height int) { return p.max.width, p.max.height }
223	
224	// Steps is the default schedule length.
225	func (p *Pipeline) Steps() int { return p.steps }
226	
227	// MaxPrompt is the text encoder's token ceiling.
228	func (p *Pipeline) MaxPrompt() int { return p.opt.MaxPrompt }
229	
230	// Residency is what the pipeline holds on the device, for a startup banner.
231	func (p *Pipeline) Residency() (encoder, transformer, vaeWeights, activations int) {
232		return p.encBytes, p.ditBytes, p.vaeBytes, p.actBytes
233	}
234	
235	// LatentFor resolves a request's size to the latent grid the transformer
236	// will denoise. A size this pipeline cannot run is an error rather than a
237	// rounded-up answer.
238	func (p *Pipeline) LatentFor(width, height int) (channels, h, w int, err error) {
239		g, err := p.geomFor(width, height)
240		if err != nil {
241			return 0, 0, 0, err
242		}
243		return p.vcfg.ZDim, g.latentH, g.latentW, nil
244	}
245	
246	func (p *Pipeline) geomFor(width, height int) (geom, error) {
247		if width == 0 {
248			width = p.def.width
249		}
250		if height == 0 {
251			height = p.def.height
252		}
253		g, err := newGeom(width, height)
254		if err != nil {
255			return geom{}, err
256		}
257		if g.width > p.max.width || g.height > p.max.height {
258			return geom{}, fmt.Errorf("pipeline: %dx%d is past this server's %dx%d ceiling",
259				g.width, g.height, p.max.width, p.max.height)
260		}
261		return g, nil
262	}
263	
264	// ErrPromptTooLong is a prompt past the text encoder's arena. It is the
265	// client's to fix, which is why it is distinguishable.
266	var ErrPromptTooLong = fmt.Errorf("prompt is longer than the text encoder's token ceiling")
267	
268	// Request is one image to generate.
269	type Request struct {
270		Prompt        string
271		Width, Height int
272		Steps         int
273		Seed          int64
274		// Latents, when given, replaces the seeded noise. It is the packed
275		// [tokens, z] layout Run works in, and it is written through: the loop
276		// integrates in place and a caller usually wants the final latent too.
277		Latents  *qwen.Mat
278		Progress func(Step)
279	}
280	
281	// Step is what a progress callback is told after each denoising step.
282	//
283	// Latents is the loop's own buffer and the next step overwrites it, so a
284	// callback that keeps it has to copy.
285	type Step struct {
286		Index int
287		Steps int
288		Wall  time.Duration
289		// Sigma and NextSigma are the noise levels this step moved between.
290		Sigma, NextSigma float64
291		Latents          *qwen.Mat
292	
293		// Preview decodes this step's *denoised estimate* through the fitted
294		// linear map (preview.go) into an image at latent resolution, in the
295		// same [-1, 1] RGBA layout the real decoder produces. It is valid only
296		// for the duration of the callback.
297		//
298		// It is a closure rather than a decoded tensor because the estimate has
299		// to be formed -- one pass over the latents -- and a callback that only
300		// wants the wall clock should not pay for it. That it is cheap enough
301		// not to need a flag is the point of Q7; that it is not *free* is why it
302		// is still lazy.
303		Preview func() (*zvae.Tensor, error)
304	}
305	
306	// Timings is what one image cost, by stage.
307	type Timings struct {
308		Encode  time.Duration // tokenizer and the text encoder
309		Prefill time.Duration // the DiT's step 0, which also fills the prefix cache
310		Steps   []time.Duration
311		Decode  time.Duration // the VAE
312		Total   time.Duration
313	
314		Tokens        int // the prompt's length after the template and the drop
315		Width, Height int
316	}
317	
318	// Generate is Run for the common case.
319	func (p *Pipeline) Generate(prompt string, seed int64, progress func(Step)) (*zvae.Tensor, *Timings, error) {
320		return p.Run(Request{Prompt: prompt, Seed: seed, Progress: progress})
321	}
322	
323	// Encode runs the tokenizer and the text encoder, returning the DiT's text
324	// embedding. It is separate because it is the one stage whose cost does not
325	// scale with the image, and because a caller sweeping step counts over one
326	// prompt should not pay for it each time.
327	func (p *Pipeline) Encode(prompt string) (*qwen.Mat, error) {
328		ids, err := textenc.EncodePrompt(p.tok, prompt)
329		if err != nil {
330			return nil, err
331		}
332		if len(ids) > p.opt.MaxPrompt {
333			return nil, fmt.Errorf("%w: %d tokens against %d", ErrPromptTooLong, len(ids), p.opt.MaxPrompt)
334		}
335		out, err := p.enc.Forward(ids)
336		if err != nil {
337			return nil, err
338		}
339		return textenc.Drop(out, p.drop)
340	}
341	
342	// Noise draws the initial packed latents for a geometry from a seeded
343	// Gaussian, in the [tokens, z] layout the DiT works in.
344	//
345	// The order is the packed buffer's own — token-major, channel-minor — which
346	// is this repo's convention rather than the reference's: diffusers seeds a
347	// torch generator over [B, C, H, W], and reproducing *its* image from a seed
348	// was never available to us. What this does guarantee is our own
349	// reproducibility, which is what a client re-sending a seed is asking for.
350	func (p *Pipeline) Noise(width, height int, seed int64) (*qwen.Mat, error) {
351		g, err := p.geomFor(width, height)
352		if err != nil {
353			return nil, err
354		}
355		return p.noise(g, seed), nil
356	}
357	
358	func (p *Pipeline) noise(g geom, seed int64) *qwen.Mat {
359		rng := rand.New(rand.NewSource(seed))
360		m := qwen.NewMat(g.imgTokens, p.vcfg.ZDim)
361		for i := range m.Data {
362			m.Data[i] = float32(rng.NormFloat64())
363		}
364		return m
365	}
366	
367	// Run renders one image: prompt through the text encoder, the DiT's sampler
368	// with the prefix KV cache, and the VAE decoder. The returned tensor is
369	// [1, 4, H, W] RGBA in [-1, 1], which is the decoder's own range.
370	func (p *Pipeline) Run(req Request) (*zvae.Tensor, *Timings, error) {
371		if p.enc == nil || p.dt == nil || p.dec == nil {
372			return nil, nil, fmt.Errorf("pipeline: destroyed")
373		}
374		g, err := p.geomFor(req.Width, req.Height)
375		if err != nil {
376			return nil, nil, err
377		}
378		steps := req.Steps
379		if steps == 0 {
380			steps = p.steps
381		}
382		if steps < 1 {
383			return nil, nil, fmt.Errorf("pipeline: %d steps", steps)
384		}
385	
386		tm := &Timings{Width: g.width, Height: g.height}
387		start := time.Now()
388	
389		embeds, err := p.Encode(req.Prompt)
390		if err != nil {
391			return nil, nil, err
392		}
393		tm.Encode = time.Since(start)
394		tm.Tokens = embeds.Rows
395	
396		lay, err := dit.NewLayout([]int{embeds.Rows}, [][3]int{{1, g.latentH, g.latentW}})
397		if err != nil {
398			return nil, nil, err
399		}
400		sched, err := p.scfg.Timesteps(steps, g.imgTokens)
401		if err != nil {
402			return nil, nil, err
403		}
404		latents := req.Latents
405		if latents == nil {
406			latents = p.noise(g, req.Seed)
407		} else if latents.Rows != g.imgTokens || latents.Cols != p.vcfg.ZDim {
408			return nil, nil, fmt.Errorf("pipeline: latents are %dx%d for a %dx%d target",
409				latents.Rows, latents.Cols, g.imgTokens, p.vcfg.ZDim)
410		}
411	
412		if err := p.dt.BeginImage(embeds, lay); err != nil {
413			return nil, nil, err
414		}
415		for i := 0; i < steps; i++ {
416			stepStart := time.Now()
417			// Step 0 is the block-causal prefill, which also extracts every
418			// block's prefix K/V; the rest decode only the target rows against
419			// that cache (IMAGE.md decision 2).
420			out, err := p.dt.Step(latents, sched.T(i), i == 0)
421			if err != nil {
422				return nil, nil, fmt.Errorf("pipeline: step %d: %w", i, err)
423			}
424			if err := sched.Step(i, latents.Data, out.Data); err != nil {
425				return nil, nil, err
426			}
427			wall := time.Since(stepStart)
428			tm.Steps = append(tm.Steps, wall)
429			if i == 0 {
430				tm.Prefill = wall
431			}
432			if req.Progress != nil {
433				// The denoised estimate, after the Euler move rather than before
434				// it, which is the cheaper of the two identities: the step has
435				// already written x_{t+1} = x_t + (s' - s) v, so
436				// x0 = x_t - s v = x_{t+1} - s' v with s' the *next* sigma. No
437				// copy of the pre-step latents is needed, and at the final step
438				// s' is zero -- correctly making x0 the latent that gets decoded.
439				sigmaNext := float64(sched.Sigmas[i+1])
440				v := out
441				req.Progress(Step{
442					Index: i, Steps: steps, Wall: wall,
443					Sigma:     float64(sched.Sigmas[i]),
444					NextSigma: sigmaNext,
445					Latents:   latents,
446					Preview: func() (*zvae.Tensor, error) {
447						x0 := latents.Clone()
448						if sigmaNext != 0 {
449							s := float32(sigmaNext)
450							for j := range x0.Data {
451								x0.Data[j] -= s * v.Data[j]
452							}
453						}
454						return PreviewDecode(x0, g.latentH, g.latentW)
455					},
456				})
457			}
458		}
459	
460		decodeStart := time.Now()
461		img, err := p.Decode(latents, g.latentH, g.latentW)
462		if err != nil {
463			return nil, nil, err
464		}
465		tm.Decode = time.Since(decodeStart)
466		tm.Total = time.Since(start)
467		return img, tm, nil
468	}
469	
470	// Decode unpacks the DiT's [tokens, z] latents into the VAE's [1, z, h, w],
471	// denormalizes them and decodes. It is exported because the step sweep and
472	// the CPU oracle both want to decode a latent they already have.
473	func (p *Pipeline) Decode(latents *qwen.Mat, latentH, latentW int) (*zvae.Tensor, error) {
474		if latents.Rows != latentH*latentW {
475			return nil, fmt.Errorf("pipeline: %d latent rows for a %dx%d grid", latents.Rows, latentH, latentW)
476		}
477		z := zvae.NewTensor(1, latents.Cols, latentH, latentW)
478		for tk := 0; tk < latents.Rows; tk++ {
479			row := latents.Row(tk)
480			for c := 0; c < latents.Cols; c++ {
481				z.Plane(0, c)[tk] = row[c]
482			}
483		}
484		p.vcfg.Denormalize(z)
485		return p.dec.Decode(z)
486	}
487	
488	// ToImage maps the decoder's [1, 4, H, W] RGBA in [-1, 1] to a picture.
489	//
490	// It is here rather than in an adapter because the fourth channel's meaning
491	// is the model's: Qwen-Image-2.1's VAE emits alpha always, and transparency
492	// is asked for *in the prompt* (the model card's phrasing) rather than by a
493	// flag. So a caller that did not ask for it still gets an alpha plane, and
494	// what to do with it is the one policy this function carries — `opaque`
495	// composites over white, which is what an ordinary PNG or a JPEG wants, and
496	// otherwise the alpha is kept.
497	//
498	// The clamp is the decoder's and has already happened; this rounds.
499	func ToImage(t *zvae.Tensor, opaque bool) *image.NRGBA {
500		img := image.NewNRGBA(image.Rect(0, 0, t.W, t.H))
501		plane := t.H * t.W
502		hasAlpha := t.C >= 4
503		at := func(c, i int) float64 {
504			// [-1, 1] to [0, 1].
505			return (float64(t.Data[c*plane+i]) + 1) / 2
506		}
507		b := func(v float64) uint8 { return uint8(math.Round(math.Min(255, math.Max(0, v*255)))) }
508		for i := 0; i < plane; i++ {
509			a := 1.0
510			if hasAlpha {
511				a = math.Min(1, math.Max(0, at(3, i)))
512			}
513			px := img.Pix[i*4:]
514			for c := 0; c < 3; c++ {
515				v := at(c, i)
516				if opaque && hasAlpha {
517					// Over white, in the straight-alpha space the tensor is in.
518					v = a*v + (1 - a)
519				}
520				px[c] = b(v)
521			}
522			if opaque {
523				px[3] = 255
524			} else {
525				px[3] = b(a)
526			}
527		}
528		return img
529	}
530

