15		qvae "strix-halo-vulkan/qimage/vae"
16		"strix-halo-vulkan/qimage/vision"
17		"strix-halo-vulkan/zimage/qwen"
18		"strix-halo-vulkan/zimage/tokenizer"
19		zvae "strix-halo-vulkan/zimage/vae"
20	)
21	
22	// The edit oracle is reference/dump_qi21_edit.py: the whole diffusers
23	// pipeline in fp32 on CPU at 256²/4 steps with one condition image, kv-cache
24	// on, `output_resolution` set to the card's own size so the pipeline's
25	// condition resize is the identity and this stays a gate on the pipeline
26	// rather than on a resampler. Regenerate with:
27	//
28	//	.venv/bin/python reference/dump_qi21_edit.py
29	const editRef = "../../reference/out/qi21edit"
30	
31	type editManifest struct {
32		Prompt          string  `json:"prompt"`
33		Size            int     `json:"size"`
34		Steps           int     `json:"steps"`
35		CondInputSize   []int   `json:"cond_input_size"`
36		CondLatentShape []int   `json:"cond_latent_shape"`
37		ImgShapes       [][]int `json:"img_shapes"`
38		PromptTokens    int     `json:"prompt_tokens"`
39		PadMaskCount    int     `json:"pad_mask_count"`
40		ResizeOutSize   []int   `json:"resize_out_size"`
41		CalcDimensions  []struct {
42			Resolution int   `json:"resolution"`
43			Src        []int `json:"src"`
44			Out        []int `json:"out"`
45		} `json:"calculate_dimensions"`
46		Tensors map[string]struct {
47			Shape []int   `json:"shape"`
48			Count int     `json:"count"`
49			Sum   float64 `json:"sum"`
50		} `json:"tensors"`
51	}
52	
53	func loadEditManifest(t *testing.T) *editManifest {
54		t.Helper()
55		buf, err := os.ReadFile(filepath.Join(editRef, "manifest.json"))
56		if err != nil {
57			t.Skipf("no reference dump in %s (%v); run reference/dump_qi21_edit.py", editRef, err)
58		}
59		var m editManifest
60		if err := json.Unmarshal(buf, &m); err != nil {
61			t.Fatal(err)
62		}
63		return &m
64	}
65	
66	func loadEditMat(t *testing.T, m *editManifest, name string) *qwen.Mat {
67		t.Helper()
68		meta, ok := m.Tensors[name]
69		if !ok {
70			t.Fatalf("reference has no tensor %q", name)
71		}
72		raw, err := os.ReadFile(filepath.Join(editRef, name+".bin"))
73		if err != nil {
74			t.Fatal(err)
75		}
76		if len(raw) != meta.Count*4 {
77			t.Fatalf("%s: %d bytes for %d float32", name, len(raw), meta.Count)
78		}
79		data := make([]float32, meta.Count)
80		for i := range data {
81			data[i] = math.Float32frombits(binary.LittleEndian.Uint32(raw[i*4:]))
82		}
83		cols := meta.Shape[len(meta.Shape)-1]
84		return &qwen.Mat{Rows: meta.Count / cols, Cols: cols, Data: data}
85	}
86	
87	// TestCalcDimensions checks the condition-image geometry against the
88	// pipeline's own `calculate_dimensions` over a spread of aspect ratios and
89	// two target resolutions. It is pure arithmetic and needs no weights, which
90	// is why it is separate: every condition image the server is ever handed
91	// goes through it, and the oracle below deliberately exercises only the
92	// identity case.
93	func TestCalcDimensions(t *testing.T) {
94		m := loadEditManifest(t)
95		if len(m.CalcDimensions) == 0 {
96			t.Skip("the dump has no calculate_dimensions cases; re-run reference/dump_qi21_edit.py")
97		}
98		for _, c := range m.CalcDimensions {
99			w, h := CalcDimensions(c.Resolution*c.Resolution, float64(c.Src[0])/float64(c.Src[1]))
100			if w != c.Out[0] || h != c.Out[1] {
101				t.Errorf("%dx%d at resolution %d: got %dx%d, want %dx%d",
102					c.Src[0], c.Src[1], c.Resolution, w, h, c.Out[0], c.Out[1])
103				continue
104			}
105			t.Logf("%4dx%-4d at %4d -> %4dx%-4d", c.Src[0], c.Src[1], c.Resolution, w, h)
106		}
107	}
108	
109	// TestLayoutFromPadMask checks the joint-sequence geometry an edit derives
110	// from the text encoder's pad mask, against the oracle's own img_shapes and
111	// token counts. No weights either — this is the piece that decides *where*
112	// every row of the prefix sits.
113	func TestLayoutFromPadMask(t *testing.T) {
114		m := loadEditManifest(t)
115		mask := loadEditMat(t, m, "image_pad_mask")
116		pad := make([]bool, mask.Rows*mask.Cols)
117		for i := range pad {
118			pad[i] = mask.Data[i] != 0
119		}
120		cond := [3]int{m.CondLatentShape[0], m.CondLatentShape[1], m.CondLatentShape[2]}
121		side := m.Size / 16
122		lay, err := dit.LayoutFromPadMask(pad, [][3]int{cond}, [3]int{1, side, side})
123		if err != nil {
124			t.Fatal(err)
125		}
126		if len(lay.ImgShapes) != len(m.ImgShapes) {
127			t.Fatalf("%d image blocks, the oracle has %d", len(lay.ImgShapes), len(m.ImgShapes))
128		}
129		for i, sh := range lay.ImgShapes {
130			want := m.ImgShapes[i]
131			if sh[0] != want[0] || sh[1] != want[1] || sh[2] != want[2] {
132				t.Errorf("image block %d is %v, the oracle says %v", i, sh, want)
133			}
134		}
135		// The prefix is the prompt's rows with each image slot expanded four-fold,
136		// which is the whole point of the mask: 85 prompt rows holding 64 slots
137		// become 21 text rows plus 256 latent rows.
138		wantPrefix := (m.PromptTokens - m.PadMaskCount) + m.PadMaskCount*4
139		if lay.PrefixLen != wantPrefix {
140			t.Errorf("prefix is %d rows, want %d", lay.PrefixLen, wantPrefix)
141		}
142		if got := lay.Seq(); got != wantPrefix+side*side {
143			t.Errorf("sequence is %d rows, want %d", got, wantPrefix+side*side)
144		}
145		// A t2i prompt has no slots, and the same constructor has to be the t2i
146		// one — otherwise the edit path is a second layout implementation.
147		flat, err := dit.LayoutFromPadMask(make([]bool, 17), nil, [3]int{1, side, side})
148		if err != nil {
149			t.Fatal(err)
150		}
151		plain, err := dit.NewLayout([]int{17}, [][3]int{{1, side, side}})
152		if err != nil {
153			t.Fatal(err)
154		}
155		if flat.PrefixLen != plain.PrefixLen || flat.Seq() != plain.Seq() || len(flat.Segments) != len(plain.Segments) {
156			t.Errorf("the t2i case disagrees with NewLayout: %d/%d rows against %d/%d",
157				flat.PrefixLen, flat.Seq(), plain.PrefixLen, plain.Seq())
158		}
159		t.Logf("%d prompt rows (%d slots) -> %d prefix rows + %d target = %d, segments %d",
160			m.PromptTokens, m.PadMaskCount, lay.PrefixLen, side*side, lay.Seq(), len(lay.Segments))
161	}
162	
163	// TestEndToEndEdit is Q8.3's gate: a condition image and a prompt through
164	// this repo's own tokenizer, vision tower, text encoder, VAE encoder, DiT,
165	// scheduler and VAE decoder — only the initial noise comes from the oracle,
166	// as data — against the 256²/4-step reference edit.
167	//
168	// It is the edit twin of TestEndToEndImage and is measured the same way: the
169	// component gates do not compose into this claim. ~68 GB of fp32 weights
170	// pass through, sequenced so the peak stays near the text encoder's 34 GB;
171	// it must run alone on the machine.
172	func TestEndToEndEdit(t *testing.T) {
173		if testing.Short() {
174			t.Skip("loads the whole fp32 edit pipeline")
175		}
176		m := loadEditManifest(t)
177	
178		// --- the condition image's two copies. The VAE reads all four channels;
179		// the tower reads the same picture flattened over white.
180		rgba := loadEditMat(t, m, "cond_rgba") // [4, H*W] folded to rows
181		cw, ch := m.CondInputSize[0], m.CondInputSize[1]
182		cond := zvae.NewTensor(1, 4, ch, cw)
183		copy(cond.Data, rgba.Data)
184		flat := flattenOverWhite(cond)
185	
186		// --- text: our tower, our mrope, our deepstack injection.
187		vcfg, err := vision.LoadConfig(model + "/text_encoder")
188		if err != nil {
189			t.Skipf("no checkpoint at %s (%v)", model, err)
190		}
191		tower, err := vision.Load(model+"/text_encoder", vcfg, 0)
192		if err != nil {
193			t.Fatal(err)
194		}
195		pixels, gridH, gridW, err := vcfg.Patchify(flat.Data, ch, cw)
196		if err != nil {
197			t.Fatal(err)
198		}
199		vout, err := tower.Forward(pixels, gridH, gridW, nil)
200		if err != nil {
201			t.Fatal(err)
202		}
203		// The negative control for the 8-bit composite, run here because the
204		// tower is staged and this is where the difference is born: the same
205		// picture composited in float instead of on the uint8 levels PIL uses.
206		// Half a level per pixel, and the port that did it this way first missed
207		// the oracle's prompt embedding by rel 11.
208		soft, _, _, err := vcfg.Patchify(flattenWith(cond, false).Data, ch, cw)
209		if err != nil {
210			t.Fatal(err)
211		}
212		softOut, err := tower.Forward(soft, gridH, gridW, nil)
213		if err != nil {
214			t.Fatal(err)
215		}
216		tower = nil
217		runtime.GC()
218	
219		tok, err := tokenizer.Load(model + "/processor")
220		if err != nil {
221			t.Fatal(err)
222		}
223		prompt, err := textenc.NewEditPrompt(tok, m.Prompt,
224			[]textenc.Grid{{T: 1, H: gridH, W: gridW}}, vcfg.SpatialMergeSize)
225		if err != nil {
226			t.Fatal(err)
227		}
228		tcfg, err := textenc.LoadConfig(model + "/text_encoder")
229		if err != nil {
230			t.Fatal(err)
231		}
232		section, err := textenc.LoadMRope(model + "/text_encoder")
233		if err != nil {
234			t.Fatal(err)
235		}
236		rope, err := prompt.MRope(tcfg.HeadDim, tcfg.RopeTheta, section)
237		if err != nil {
238			t.Fatal(err)
239		}
240		drop, err := textenc.DropTokens(tok)
241		if err != nil {
242			t.Fatal(err)
243		}
244		te, err := qwen.LoadWith(model+"/text_encoder", tcfg, tcfg.NumLayers)
245		if err != nil {
246			t.Fatal(err)
247		}
248		embeds, padMask, err := prompt.Encode(te, rope,
249			[]textenc.Condition{{Merged: vout.Merged, Deepstack: vout.Deepstack}}, drop, nil)
250		if err != nil {
251			t.Fatal(err)
252		}
253		embeds = embeds.Clone()
254		compareStepAt(t, "prompt_embeds", embeds, loadEditMat(t, m, "prompt_embeds"), embedSpec)
255	
256		// The control, with the text model still staged: the float composite's
257		// vision rows through the same encoder. It has to land far outside the
258		// bound, or "composite on the levels" is a preference rather than a
259		// requirement.
260		softEmbeds, _, err := prompt.Encode(te, rope,
261			[]textenc.Condition{{Merged: softOut.Merged, Deepstack: softOut.Deepstack}}, drop, nil)
262		if err != nil {
263			t.Fatal(err)
264		}
265		wantEmbeds := loadEditMat(t, m, "prompt_embeds")
266		if rel := relDeviation(softEmbeds, wantEmbeds); rel <= embedSpec {
267			t.Errorf("the float composite still matches at rel %.3g, inside the %.0e bound", rel, embedSpec)
268		} else {
269			t.Logf("control %-28s rel %.3g, %.0fx the bound (merged rows differ by %.3g)",
270				"float composite, not 8-bit", rel, rel/embedSpec, relDeviation(softOut.Merged, vout.Merged))
271		}
272		te = nil
273		runtime.GC()
274	
275		// --- the condition latents, which are the other half of the prefix.
276		vaecfg, err := qvae.LoadConfig(model + "/vae")
277		if err != nil {
278			t.Fatal(err)
279		}
280		enc, err := qvae.LoadEncoder(model+"/vae", vaecfg)
281		if err != nil {
282			t.Fatal(err)
283		}
284		condLatents, condShape, err := EncodeCondition(enc, vaecfg, cond)
285		if err != nil {
286			t.Fatal(err)
287		}
288		enc = nil
289		runtime.GC()
290		compareStepAt(t, "cond_latents", condLatents, loadEditMat(t, m, "cond_latents"), condSpec)
291		if want := m.CondLatentShape; condShape[1] != want[1] || condShape[2] != want[2] {
292			t.Fatalf("condition latents are %v, the oracle says %v", condShape, want)
293		}
294	
295		// --- denoise from the oracle's noise, with the prefix in front.
296		dcfg, err := dit.LoadConfig(transformer)
297		if err != nil {
298			t.Fatal(err)
299		}
300		dm, err := dit.Load(transformer, dcfg.NumLayers)
301		if err != nil {
302			t.Fatal(err)
303		}
304		side := m.Size / 16
305		lay, err := dit.LayoutFromPadMask(padMask, [][3]int{condShape}, [3]int{1, side, side})
306		if err != nil {
307			t.Fatal(err)
308		}
309		scfg, err := LoadSchedConfig(model + "/scheduler")
310		if err != nil {
311			t.Fatal(err)
312		}
313		// The shift is a function of the *target* token count, not the joint
314		// sequence — a bigger prefix does not move the schedule.
315		sched, err := scfg.Timesteps(m.Steps, side*side)
316		if err != nil {
317			t.Fatal(err)
318		}
319		steps := map[int]*qwen.Mat{}
320		latents, err := Denoise(dm, embeds, lay, condLatents, loadEditMat(t, m, "noise"), sched,
321			func(step int, l *qwen.Mat) { steps[step] = l.Clone() })
322		if err != nil {
323			t.Fatal(err)
324		}
325		dm = nil
326		runtime.GC()
327		for i := 0; i < m.Steps; i++ {
328			compareStepAt(t, fmt.Sprintf("step%d_latents", i), steps[i],
329				loadEditMat(t, m, fmt.Sprintf("step%d_latents", i)), latentSpec)
330		}
331	
332		// --- decode and compare the picture.
333		dec, err := qvae.LoadDecoder(model+"/vae", vaecfg)
334		if err != nil {
335			t.Fatal(err)
336		}
337		z, err := UnpackLatents(latents, side, side)
338		if err != nil {
339			t.Fatal(err)
340		}
341		vaecfg.Denormalize(z)
342		img, err := dec.Decode(z)
343		if err != nil {
344			t.Fatal(err)
345		}
346		want := loadEditMat(t, m, "image") // [H*W, 4] in [0, 1]
347		var maxAbs, sumAbs float64
348		for h := 0; h < img.H; h++ {
349			for w := 0; w < img.W; w++ {
350				for c := 0; c < img.C; c++ {
351					got := (float64(img.Plane(0, c)[h*img.W+w]) + 1) / 2
352					d := math.Abs(got - float64(want.Row(h*img.W+w)[c]))
353					if d > maxAbs {
354						maxAbs = d
355					}
356					sumAbs += d
357				}
358			}
359		}
360		mean := sumAbs / float64(img.C*img.H*img.W)
361		if maxAbs > imgSpec {
362			t.Errorf("edited image: max abs %.5f (mean %.6f) > %.3g against the oracle", maxAbs, mean, imgSpec)
363			return
364		}
365		t.Logf("edited image: max abs %.5f, mean %.6f against the oracle (bound %.3g)", maxAbs, mean, imgSpec)
366	}
367	
368	// relDeviation is compareStepAt's metric without the assertion, for the
369	// controls: the worst per-element deviation, floored by the reference's rms
370	// so a small element cannot dominate.
371	func relDeviation(got, want *qwen.Mat) float64 {
372		var sumSq float64
373		for i := range want.Data {
374			sumSq += float64(want.Data[i]) * float64(want.Data[i])
375		}
376		rms := math.Sqrt(sumSq / float64(len(want.Data)))
377		var rel float64
378		for i := range want.Data {
379			d := math.Abs(float64(got.Data[i]) - float64(want.Data[i]))
380			if r := d / math.Max(math.Abs(float64(want.Data[i])), math.Max(rms, 1e-12)); r > rel {
381				rel = r
382			}
383		}
384		return rel
385	}
386	
387	// condSpec is the bound on the condition latents. The VAE encoder's own gate
388	// (qimage/vae) measures the posterior mode at 4.7e-5 against the dump, and
389	// nothing here is deeper than that — this is the same encoder over the same
390	// card, so the bound is the encoder's, not a new one.
391	const condSpec = 2e-4
392	
393	// latentSpec is Q3's per-step bound, measured there at 2.1e-5 to 2.5e-4 over
394	// the t2i oracle's four steps.
395	const latentSpec = 1e-3
396	
397	// flattenOverWhite composites an RGBA condition image over white and drops
398	// the alpha, which is the copy the *vision tower* reads. The VAE reads the
399	// four-channel original; the pipeline flattens once, for one of the two
400	// encoders, and a port that flattens for both is wrong only on transparent
401	// references — which is exactly the case this model exists to serve.
402	//
403	// **The composite is done in 8-bit**, because the reference's is: PIL's
404	// `paste` works on the uint8 image, so every composited pixel lands on a
405	// level. Doing the same arithmetic in float leaves 97% of the pixels half a
406	// level away from the reference's, and this file's own negative control
407	// measures what that costs downstream — it is not a rounding detail, it is
408	// the difference between reproducing the oracle and not. A served edit is
409	// handed an 8-bit PNG, so quantizing here is also what the real input
410	// looks like.
411	func flattenOverWhite(rgba *zvae.Tensor) *zvae.Tensor {
412		return flattenWith(rgba, true)
413	}
414	
415	func flattenWith(rgba *zvae.Tensor, quantize bool) *zvae.Tensor {
416		out := zvae.NewTensor(1, 3, rgba.H, rgba.W)
417		alpha := rgba.Plane(0, 3)
418		for c := 0; c < 3; c++ {
419			src, dst := rgba.Plane(0, c), out.Plane(0, c)
420			for i := range dst {
421				// [-1, 1] to [0, 1], composite over white, quantize, and back.
422				a := (float64(alpha[i]) + 1) / 2
423				v := (float64(src[i]) + 1) / 2
424				c := v*a + (1 - a)
425				if quantize {
426					dst[i] = float32(math.Round(c*255)/127.5 - 1)
427					continue
428				}
429				dst[i] = float32(c*2 - 1)
430			}
431		}
432		return out
433	}
