1	package textenc
2	
3	// The edit path's text encoding: everything a condition image changes about
4	// the prompt before the DiT sees it (IMAGE.md Q8).
5	//
6	// A generation's prompt is a flat run of text tokens at positions 0..T-1. An
7	// edit's is not, and the three differences are the whole of this file:
8	//
9	//  1. **The template carries image runs.** Each condition image contributes
10	//     `<imageN><|vision_start|>…<|vision_end|>`, and the processor expands
11	//     that single `<|image_pad|>` into one pad token per *merged* 2x2 patch
12	//     group — 64 of them for a 256x256 image. The pads are rendered here for
13	//     the same reason: the tokenizer must see the sequence the checkpoint was
14	//     trained on, not a placeholder.
15	//  2. **The positions are 3-D.** Text tokens take (p, p, p) off a counter,
16	//     but an image block lays its merged grid out as (start, start+h,
17	//     start+w) and advances the counter by max(H, W)/merge — so a 16x16-patch
18	//     image costs 8 positions, not 64. The rotary table is then *interleaved*
19	//     rather than blocked: frequency j reads the h axis when j%3 == 1 and the
20	//     w axis when j%3 == 2, below 3*section, and the t axis everywhere else.
21	//     Q0 measured that for a text-only prompt this collapses to the plain
22	//     theta-5e6 table exactly (mrope_gap 0), which is why the t2i path above
23	//     needs none of it.
24	//  3. **The tower reaches into the first three layers.** The merger's rows
25	//     are scattered into the image-pad slots before layer 0, and the three
26	//     deepstack features are *added* at those same slots after layers 0, 1
27	//     and 2. Nothing else carries vision content: the DiT overwrites the
28	//     image rows with VAE latents, so what survives is only what the
29	//     surrounding text tokens absorbed through attention.
30	//
31	// The vision tower itself is qimage/vision, and it is deliberately not
32	// imported here — a Condition is whatever produced those rows, which keeps
33	// this package's dependencies the tokenizer and the transformer, and lets
34	// the gate feed either the tower's output or the dump's.
35	
36	import (
37		"encoding/json"
38		"fmt"
39		"math"
40		"os"
41		"path/filepath"
42		"strings"
43	
44		"strix-halo-vulkan/zimage/qwen"
45		"strix-halo-vulkan/zimage/tokenizer"
46	)
47	
48	// ImagePad is the token every merged patch group of a condition image
49	// occupies in the text sequence.
50	const ImagePad = "<|image_pad|>"
51	
52	// Grid is one condition image's patch grid, as the processor reports it in
53	// image_grid_thw: T frames of H x W patches, *before* the 2x2 spatial merge.
54	// A still image is T = 1 (the temporal patch size folds two copies of the
55	// same frame into one patch, so it does not appear here).
56	type Grid struct{ T, H, W int }
57	
58	// Tokens is how many `<|image_pad|>` slots this grid occupies: the patch
59	// count divided by the merge square.
60	func (g Grid) Tokens(merge int) int { return g.T * g.H * g.W / (merge * merge) }
61	
62	// Span is how far the position counter advances across this image — max(H, W)
63	// over the merge, not the token count. Two images of the same token count and
64	// different aspect ratios therefore occupy different position spans.
65	func (g Grid) Span(merge int) int { return max(g.H, g.W) / merge }
66	
67	// MRopeSection is the checkpoint's [t, h, w] split of the rotary frequencies,
68	// 24/20/20 here, summing to head_dim/2.
69	type MRopeSection [3]int
70	
71	// LoadMRope reads the text encoder's mrope configuration. It refuses a
72	// checkpoint that is not interleaved rather than quietly running the blocked
73	// layout, which produces numbers and not an error.
74	func LoadMRope(dir string) (MRopeSection, error) {
75		var zero MRopeSection
76		buf, err := os.ReadFile(filepath.Join(dir, "config.json"))
77		if err != nil {
78			return zero, err
79		}
80		var outer struct {
81			Text struct {
82				RopeScaling struct {
83					Section     []int `json:"mrope_section"`
84					Interleaved bool  `json:"mrope_interleaved"`
85				} `json:"rope_scaling"`
86			} `json:"text_config"`
87		}
88		if err := json.Unmarshal(buf, &outer); err != nil {
89			return zero, fmt.Errorf("textenc: parsing config.json: %w", err)
90		}
91		s := outer.Text.RopeScaling
92		if len(s.Section) != 3 {
93			return zero, fmt.Errorf("textenc: mrope_section is %v, want three axes", s.Section)
94		}
95		if !s.Interleaved {
96			return zero, fmt.Errorf("textenc: mrope_interleaved is false; this port implements the interleaved layout")
97		}
98		return MRopeSection{s.Section[0], s.Section[1], s.Section[2]}, nil
99	}
100	
101	// TemplateTI2I renders the edit template for n condition images, before the
102	// processor expands the pads — the string diffusers builds and formats.
103	func TemplateTI2I(prompt string, n int) string {
104		pads := make([]int, n)
105		for i := range pads {
106			pads[i] = 1
107		}
108		return RenderEdit(prompt, pads)
109	}
110	
111	// RenderEdit renders an edit prompt with each image's pad token already
112	// repeated the number of times the processor would repeat it.
113	//
114	// The leading space before the second and later images is the reference's,
115	// and it tokenizes: dropping it shifts every id after the first image.
116	func RenderEdit(prompt string, pads []int) string {
117		if prompt == "" {
118			prompt = " "
119		}
120		var b strings.Builder
121		b.WriteString(sysRendered)
122		b.WriteString("<|im_start|>user\n")
123		for i, n := range pads {
124			if i > 0 {
125				b.WriteString(" ")
126			}
127			fmt.Fprintf(&b, "<image%d><|vision_start|>%s<|vision_end|>",
128				i+1, strings.Repeat(ImagePad, n))
129		}
130		b.WriteString(prompt)
131		b.WriteString("<|im_end|>\n<|im_start|>assistant\n")
132		return b.String()
133	}
134	
135	// EditPrompt is a tokenized edit prompt: the ids, where the image slots are,
136	// and the 3-D positions each token sits at.
137	type EditPrompt struct {
138		IDs   []int32
139		Grids []Grid
140		Merge int
141		PadID int32
142		// Pads holds the sequence index of every image-pad token, in order, so
143		// the conditions' rows scatter into them by position.
144		Pads []int
145		// Pos is [t, h, w] over the sequence — transformers' get_rope_index.
146		Pos [3][]int32
147	}
148	
149	// NewEditPrompt renders, tokenizes and positions an edit prompt.
150	//
151	// grids come from the image processor's own geometry (qimage/vision's
152	// Patchify returns them) and must be in the order the images were passed,
153	// which is the order their runs appear in the template.
154	func NewEditPrompt(tok *tokenizer.Tokenizer, prompt string, grids []Grid, merge int) (*EditPrompt, error) {
155		if len(grids) == 0 {
156			return nil, fmt.Errorf("textenc: an edit prompt needs at least one condition image")
157		}
158		padID, ok := tok.ID(ImagePad)
159		if !ok {
160			return nil, fmt.Errorf("textenc: the tokenizer has no %s token", ImagePad)
161		}
162		pads := make([]int, len(grids))
163		for i, g := range grids {
164			if g.T <= 0 || g.H%merge != 0 || g.W%merge != 0 {
165				return nil, fmt.Errorf("textenc: image %d has grid %v, which does not merge by %d", i, g, merge)
166			}
167			pads[i] = g.Tokens(merge)
168		}
169		ids, err := tok.Encode(RenderEdit(prompt, pads))
170		if err != nil {
171			return nil, err
172		}
173		p := &EditPrompt{IDs: ids, Grids: grids, Merge: merge, PadID: padID}
174		for i, id := range ids {
175			if id == padID {
176				p.Pads = append(p.Pads, i)
177			}
178		}
179		if want := sum(pads); len(p.Pads) != want {
180			return nil, fmt.Errorf("textenc: tokenized %d image slots, the grids want %d", len(p.Pads), want)
181		}
182		if p.Pos, err = p.positions(); err != nil {
183			return nil, err
184		}
185		return p, nil
186	}
187	
188	func sum(v []int) int {
189		t := 0
190		for _, x := range v {
191			t += x
192		}
193		return t
194	}
195	
196	// positions is transformers' get_rope_index over one sequence with no
197	// padding: runs of text advance all three axes together off a shared
198	// counter, and each image run lays its merged grid out in (t, h, w) raster
199	// order starting at the counter, which then advances by the grid's *span*.
200	func (p *EditPrompt) positions() ([3][]int32, error) {
201		var pos [3][]int32
202		for a := range pos {
203			pos[a] = make([]int32, len(p.IDs))
204		}
205		cur, img, i := 0, 0, 0
206		for i < len(p.IDs) {
207			if p.IDs[i] != p.PadID {
208				for ; i < len(p.IDs) && p.IDs[i] != p.PadID; i++ {
209					for a := range pos {
210						pos[a][i] = int32(cur)
211					}
212					cur++
213				}
214				continue
215			}
216			run := 0
217			for j := i; j < len(p.IDs) && p.IDs[j] == p.PadID; j++ {
218				run++
219			}
220			if img >= len(p.Grids) {
221				return pos, fmt.Errorf("textenc: %d image runs for %d grids", img+1, len(p.Grids))
222			}
223			g := p.Grids[img]
224			if run != g.Tokens(p.Merge) {
225				return pos, fmt.Errorf("textenc: image %d has a run of %d pads, grid %v wants %d",
226					img, run, g, g.Tokens(p.Merge))
227			}
228			lh, lw := g.H/p.Merge, g.W/p.Merge
229			for t := 0; t < g.T; t++ {
230				for h := 0; h < lh; h++ {
231					for w := 0; w < lw; w++ {
232						pos[0][i] = int32(cur + t)
233						pos[1][i] = int32(cur + h)
234						pos[2][i] = int32(cur + w)
235						i++
236					}
237				}
238			}
239			cur += g.Span(p.Merge)
240			img++
241		}
242		if img != len(p.Grids) {
243			return pos, fmt.Errorf("textenc: %d image runs for %d grids", img, len(p.Grids))
244		}
245		return pos, nil
246	}
247	
248	// MRope builds the interleaved multimodal rotary table for this prompt.
249	//
250	// The three axes each get the full set of head_dim/2 inverse frequencies, and
251	// the table is then recomposed frequency by frequency: index j reads the h
252	// axis when j%3 == 1 and j < 3*section[1], the w axis when j%3 == 2 and
253	// j < 3*section[2], and the t axis otherwise — which leaves section[0] of
254	// them on t, the four above 3*section[1] among them. transformers duplicates
255	// the result to the full head width; qwen.RoPE keeps the distinct half and
256	// indexes it twice, so this returns the half.
257	func (p *EditPrompt) MRope(headDim int, theta float64, section MRopeSection) (*qwen.RoPE, error) {
258		half := headDim / 2
259		if section[0]+section[1]+section[2] != half {
260			return nil, fmt.Errorf("textenc: mrope section %v does not sum to %d", section, half)
261		}
262		T := len(p.IDs)
263		r := &qwen.RoPE{HeadDim: headDim, Cos: make([]float32, T*half), Sin: make([]float32, T*half)}
264		for j := 0; j < half; j++ {
265			axis := 0
266			switch {
267			case j%3 == 1 && j < 3*section[1]:
268				axis = 1
269			case j%3 == 2 && j < 3*section[2]:
270				axis = 2
271			}
272			freq := 1 / math.Pow(theta, float64(2*j)/float64(headDim))
273			for t := 0; t < T; t++ {
274				angle := float64(p.Pos[axis][t]) * freq
275				r.Cos[t*half+j] = float32(math.Cos(angle))
276				r.Sin[t*half+j] = float32(math.Sin(angle))
277			}
278		}
279		return r, nil
280	}
281	
282	// Condition is one condition image as the vision tower produced it: the
283	// merger's rows, which are scattered into that image's pad slots, and the
284	// deepstack features, which are added at those slots after the text model's
285	// first layers.
286	type Condition struct {
287		Merged    *qwen.Mat
288		Deepstack []*qwen.Mat
289	}
290	
291	// Embeddings looks the ids up and scatters the conditions' merged rows into
292	// the image slots — the model's `inputs_embeds`, which the dump measured
293	// identical to this construction (scatter_gap 0).
294	func (p *EditPrompt) Embeddings(model *qwen.Model, conds []Condition) (*qwen.Mat, error) {
295		if len(conds) != len(p.Grids) {
296			return nil, fmt.Errorf("textenc: %d conditions for %d image runs", len(conds), len(p.Grids))
297		}
298		x, err := model.Embeddings(p.IDs)
299		if err != nil {
300			return nil, err
301		}
302		slot := 0
303		for i, c := range conds {
304			want := p.Grids[i].Tokens(p.Merge)
305			if c.Merged == nil || c.Merged.Rows != want {
306				return nil, fmt.Errorf("textenc: condition %d has %v merged rows, grid %v wants %d",
307					i, c.Merged, p.Grids[i], want)
308			}
309			if c.Merged.Cols != x.Cols {
310				return nil, fmt.Errorf("textenc: condition %d is %d wide, the model is %d", i, c.Merged.Cols, x.Cols)
311			}
312			for r := 0; r < c.Merged.Rows; r++ {
313				copy(x.Row(p.Pads[slot]), c.Merged.Row(r))
314				slot++
315			}
316		}
317		return x, nil
318	}
319	
320	// Encode runs the text encoder over the edit prompt and returns the rows the
321	// DiT consumes together with the image-pad mask that tells it which of them
322	// stand for a condition image's latents.
323	//
324	// rope is a parameter rather than built here so the gate can hand it the
325	// plain t2i table as a negative control: swapping the two changes numbers
326	// and not shapes.
327	func (p *EditPrompt) Encode(model *qwen.Model, rope *qwen.RoPE, conds []Condition, drop int, tr qwen.Trace) (*qwen.Mat, []bool, error) {
328		x, err := p.Embeddings(model, conds)
329		if err != nil {
330			return nil, nil, err
331		}
332		// transformers' name for the post-scatter tensor, and deliberately not
333		// qwen.Forward's "embeddings": that one is the raw lookup, this one has
334		// the tower's rows in it.
335		tr.Put("inputs_embeds", x)
336		deep, err := p.deepstack(conds, x.Cols)
337		if err != nil {
338			return nil, nil, err
339		}
340		out, err := model.ForwardEmbeds(x, rope, tr, func(layer int, h *qwen.Mat) error {
341			if layer >= len(deep) {
342				return nil
343			}
344			f := deep[layer]
345			for i, row := range p.Pads {
346				dst, src := h.Row(row), f.Row(i)
347				for c := range dst {
348					dst[c] += src[c]
349				}
350			}
351			return nil
352		})
353		if err != nil {
354			return nil, nil, err
355		}
356		embeds, err := Drop(out, drop)
357		if err != nil {
358			return nil, nil, err
359		}
360		return embeds, p.PadMask(drop), nil
361	}
362	
363	// deepstack concatenates the conditions' features layer by layer, in pad
364	// order — the text model adds one tensor per layer over *all* the images'
365	// slots at once, so several images are one stacked matrix and not a loop.
366	func (p *EditPrompt) deepstack(conds []Condition, cols int) ([]*qwen.Mat, error) {
367		n := len(conds[0].Deepstack)
368		out := make([]*qwen.Mat, n)
369		for l := 0; l < n; l++ {
370			out[l] = qwen.NewMat(len(p.Pads), cols)
371			slot := 0
372			for i, c := range conds {
373				if len(c.Deepstack) != n {
374					return nil, fmt.Errorf("textenc: condition %d has %d deepstack features, condition 0 has %d",
375						i, len(c.Deepstack), n)
376				}
377				f := c.Deepstack[l]
378				if f.Rows != p.Grids[i].Tokens(p.Merge) || f.Cols != cols {
379					return nil, fmt.Errorf("textenc: condition %d deepstack %d is %v", i, l, f)
380				}
381				for r := 0; r < f.Rows; r++ {
382					copy(out[l].Row(slot), f.Row(r))
383					slot++
384				}
385			}
386		}
387		return out, nil
388	}
389	
390	// PadMask is the image_pad_mask the DiT reads: true where a row of the
391	// prompt embedding stands for a condition image's token, over the rows that
392	// survive the system-prefix drop.
393	func (p *EditPrompt) PadMask(drop int) []bool {
394		mask := make([]bool, len(p.IDs)-drop)
395		for _, i := range p.Pads {
396			if i >= drop {
397				mask[i-drop] = true
398			}
399		}
400		return mask
401	}
402

