func (g *GPUEncoder) allocActivations() error {
	c := g.cfg
	q := c.NumHeads * c.HeadDim
	kv := c.NumKVHeads * c.HeadDim
	rows := g.arenaRows

	alloc := func(n int) uint32 {
		off := uint32(g.actElems)
		g.actElems += (n + 63) &^ 63
		return off
	}
	g.aX = alloc(rows * c.HiddenSize)
	g.aQ = alloc(rows * q)
	g.aK = alloc(rows * kv)
	g.aV = alloc(rows * kv)
	g.aCtx = alloc(rows * q)
	g.aAttn = alloc(rows * c.HiddenSize)
	g.aGate = alloc(rows * c.IntermediateSize)
	g.aUp = alloc(rows * c.IntermediateSize)
	g.aFF = alloc(rows * c.HiddenSize)

	halloc := func(n int) uint32 {
		off := uint32(g.hElems)
		g.hElems += (n + 63) &^ 63
		return off
	}
	g.hA = halloc(rows * g.ldaDim)
	g.hQ = halloc(c.NumHeads * rows * c.HeadDim)
	g.hK = halloc(c.NumKVHeads * rows * c.HeadDim)
	g.hV = halloc(c.NumKVHeads * rows * c.HeadDim)
	g.hCtx = halloc(rows * g.ldaQ)
	g.hFFN = halloc(rows * g.ldaFFN)

	var err error
	if g.abuf, err = g.dev.NewBuffer(g.actElems * 4); err != nil {
		return fmt.Errorf("qwen: fp32 activation arena (%d MB): %w", (g.actElems*4)>>20, err)
	}
	if g.hbuf, err = g.dev.NewBuffer(g.hElems * 2); err != nil {
		return fmt.Errorf("qwen: fp16 activation arena (%d MB): %w", (g.hElems*2)>>20, err)
	}
	// Zeroed once: the pad rows and pad columns of every A operand come from
	// here, and a short run leaves them as a longer one wrote them.
	g.hbuf.WriteFloat32(make([]float32, g.hElems/2))
	return nil
}

// build compiles every pipeline over all four arenas. They are bound to every
// pipeline, used or not, so that one descriptor layout and one push-constant
// size serve the whole sequence, which is what vk.DispatchMultiTimed needs to
// record it into a single command buffer.
func (g *GPUEncoder) build() error {
====
#version 450
// The gated residual: x += gate * y, with gate a row vector broadcast down
// the sequence.
//
// Both of the block's residuals have this shape -- attention's and the feed
// forward's -- and in both the gate comes from adaLN (dit_adaln.comp) and so
// lives in the activation arena rather than the weight arena, which is why
// its offset is pc.aux0 and not pc.wOff.
//
// x is updated in place: the residual stream is one tensor for the whole
// block, which is what lets stage 4 run 34 of these back to back without a
// copy between them.
//
// pc.aux2 = 0 drops the gate, which is the context refiner's path: two of the
// DiT's 34 blocks are built with modulation=False and add their branch output
// to the residual ungated (stage 4c).

#include "dit_common.glsl"

layout(local_size_x = 256) in;

void main() {
    uint r = gl_WorkGroupID.x;
    if (r >= pc.tokens) {
        return;
    }
    // One workgroup per row rather than a flat grid: the gate is indexed by
    // the column, and a flat grid would pay an integer division by a width
    // that is not a power of two (3840) on every element (IDEAS §1.2).
    uint base = r * pc.dim;
    for (uint c = gl_LocalInvocationID.x; c < pc.dim; c += 256u) {
        float v = act[pc.inOff + base + c];
        if (pc.aux2 != 0u) {
            v *= act[pc.aux0 + c];
        }
        act[pc.outOff + base + c] += v;
    }
}

