	var cached time.Duration
	for i := 0; i < steps; i++ {
		start := time.Now()
		if _, err := g.Step(latents, sched.T(i), i == 0); err != nil {
			t.Fatalf("step %d: %v", i, err)
		}
		w := time.Since(start)
		if i == 0 {
			prefill = w
		} else {
			cached += w
		}
